public static Result<TripCompletion> Complete(Trip trip, DateTime completedAt) =>
    trip.Status != TripStatus.Active
        ? Result.Failure<TripCompletion>("Trip is not active.")
        : Result.Success(new TripCompletion(
            trip.Complete(completedAt, requiresReview: trip.Distance > 100),
            new TripCompleted(trip.Id, completedAt, trip.Distance)));
// shell
var trip   = await repo.Get(id);
var result = TripCompletionService.Complete(trip, clock.UtcNow);
if (result.IsFailure) return BadRequest(result.Error);
await repo.Save(result.Value.Trip);
await bus.Publish(result.Value.Event);

