// shell: load → (pure) decide → save/publish, no business ifs
var sandwich =
    from id        in ParseGuid(rawId)
    from trip      in LoadTrip(id)                       // Task<Either<...>>
    let  completed  = TripCompletionService.Complete(trip, clock.UtcNow)  // pure
    from saved     in completed.Match(
                          ok  => SaveAndPublish(ok),
                          err => Task.FromResult(Result.Failure(err)))
    select saved;
Either<ActionResult, OkObjectResult> result = await sandwich;
return result.Match(x => x, x => x);
